<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {Table2,History,Activity,HeartPulse,TriangleAlert,LoaderCircle,RefreshCw,Download} from 'lucide-vue-next';
type Item=Record<string,any>;
const props=defineProps<{tenant:string;resource:Item;download?:(path:string,name:string,isCurrent:()=>boolean)=>Promise<void>;request:(path:string,method?:string,data?:unknown)=>Promise<any>}>();
const result=ref<Item|null>(null);const busy=ref(false);const error=ref('');const selected=ref('');const downloading=ref(false);let generation=0;
const choices=computed(()=>({writeback:[{action:'data',label:'Amostra dos registros',icon:Table2},{action:'history',label:'Histórico de importações',icon:History}],table:[{action:'data',label:'Amostra dos dados',icon:Table2}],flow:[{action:'status',label:'Última execução',icon:Activity},{action:'history',label:'Histórico de cargas',icon:History}],schedule:[{action:'history',label:'Histórico da agenda',icon:History}],agent:[{action:'health',label:'Saúde do agente',icon:HeartPulse},{action:'events',label:'Ocorrências',icon:TriangleAlert}]} as Record<string,Item[]>)[props.resource.kind]??[]);
const historyHasCounters=computed(()=>result.value?.history?.some((execution:Item)=>typeof execution.rows_in==='number'||typeof execution.rows_out==='number')??false);
const healthFacts=computed(()=>{const h=result.value?.health;if(!h)return [];return [['Conectividade',h.online===null?'Não informada':h.online?'Online':'Offline'],['Disponibilidade (24h)',h.uptime_percent===null?'Não informada':number(h.uptime_percent)+'%'],['Trabalhos ativos',number(h.active_jobs)],['Na fila',number(h.queued_jobs)],['Memória em uso',bytes(h.used_memory_bytes)],['Limite de memória',bytes(h.memory_limit_bytes)]];});
function number(value:unknown){return typeof value==='number'?value.toLocaleString('pt-BR'):value===null||value===undefined?'—':String(value);}
function bytes(value:unknown){return typeof value==='number'?(value/1024/1024).toLocaleString('pt-BR',{maximumFractionDigits:1})+' MB':'Não informada';}
function date(value:string|null){if(!value)return '—';return new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'});}
function state(value:string){return ({succeeded:'Concluída com sucesso',failed:'Falha',running:'Em execução',queued:'Na fila',cancelled:'Cancelada',unknown:'Sem confirmação',completed:'Concluída no BI',partial:'Concluída com ocorrências',reverted:'Desfeita',ok:'Disponível',degraded:'Degradado',offline:'Offline',MISSED:'Não iniciou',LATE:'Atraso',ERROR:'Erro',CRASHED:'Interrompida'} as Record<string,string>)[value]??value;}
async function inspect(action:string){const version=++generation;selected.value=action;busy.value=true;error.value='';result.value=null;try{const report=await props.request(`/catalog/${props.tenant}/resources/${props.resource.kind}/${props.resource.id}/inspect/${action}`);if(version===generation)result.value=report;}catch(e){if(version===generation)error.value=(e as Error).message;}finally{if(version===generation)busy.value=false;}}
async function exportSpreadsheet(){
 if(!props.download||busy.value||downloading.value)return;const version=++generation;downloading.value=true;error.value='';
 try{await props.download(`/catalog/${props.tenant}/writebacks/${props.resource.id}/export`,`cadastro-${props.resource.id}.xlsx`,()=>version===generation);}
 catch(e){if(version===generation)error.value=(e as Error).message;}
 finally{if(version===generation)downloading.value=false;}
}
watch([()=>props.tenant,()=>props.resource.ref],()=>{generation++;result.value=null;error.value='';busy.value=false;downloading.value=false;selected.value='';});
onUnmounted(()=>generation++);
</script>
<template>
 <section v-if="choices.length" class="resource-inspector"><h3>{{resource.kind==='writeback'?'Registros e importações':'Conferir no BI'}}</h3><div class="inspector-actions"><button v-for="choice in choices" :key="choice.action" class="secondary-button" :class="{active:selected===choice.action}" :disabled="busy||downloading" @click="inspect(choice.action)"><component :is="choice.icon" :size="15"/>{{choice.label}}</button><button v-if="resource.kind==='writeback'&&download" class="secondary-button" :disabled="busy||downloading" @click="exportSpreadsheet"><LoaderCircle v-if="downloading" :size="15" class="spin"/><Download v-else :size="15"/>{{downloading?'Preparando planilha…':'Exportar XLSX'}}</button><button v-if="result" class="icon-button" aria-label="Atualizar consulta do recurso" :disabled="busy||downloading" @click="inspect(selected)"><RefreshCw :size="15"/></button></div>
  <p v-if="resource.kind==='writeback'&&download" class="catalog-footnote">A planilha inclui todos os registros e colunas permitidos pela sua conta, além da amostra mostrada aqui.</p>
  <p v-if="busy" class="resource-note" role="status"><LoaderCircle :size="15" class="spin"/> Consultando informações atuais…</p><p v-if="error" class="form-error" role="alert">{{error}}</p>
  <div v-if="result" class="inspector-report"><p v-if="result.message" class="resource-note">{{result.message}}</p>
   <template v-if="result.table"><div v-if="result.table.rows.length" class="catalog-table-scroll"><table><thead><tr><th v-for="column in result.table.columns" :key="column">{{result.table.column_labels?.[column]??column}}</th></tr></thead><tbody><tr v-for="(row,index) in result.table.rows" :key="index"><td v-for="column in result.table.columns" :key="column">{{number(row[column])}}</td></tr></tbody></table></div><p v-else class="resource-note">A consulta não retornou linhas.</p></template>
   <template v-if="result.history"><p v-if="!result.history.length" class="resource-note">Nenhuma execução retornada pelo BI.</p><div v-else class="execution-list"><article v-for="(execution,index) in result.history" :key="execution.id??index"><header><strong :class="['execution-state',execution.state]">{{state(execution.state)}}</strong><small v-if="execution.duration_ms!==null">{{number(execution.duration_ms/1000)}} s</small></header><dl><div><dt>Início</dt><dd>{{date(execution.started_at)}}</dd></div><div><dt>Término</dt><dd>{{date(execution.finished_at)}}</dd></div><div v-if="typeof execution.rows_in==='number'"><dt>Linhas de entrada</dt><dd>{{number(execution.rows_in)}}</dd></div><div v-if="typeof execution.rows_out==='number'"><dt>Linhas de saída</dt><dd>{{number(execution.rows_out)}}</dd></div></dl><p v-if="execution.message" class="resource-note">{{execution.message}}</p><small v-if="execution.id" class="execution-id">Execução {{execution.id}}</small></article></div><p v-if="historyHasCounters" class="resource-note">Contadores do processamento informados pelo BI; não comprovam a quantidade de registros na tabela. Uma mesma linha pode passar por várias etapas. Confira os dados e os indicadores da tabela.</p></template>
   <template v-if="result.imports"><p v-if="!result.imports.length" class="resource-note">Nenhuma importação retornada pelo BI.</p><div v-else class="execution-list"><article v-for="(batch,index) in result.imports" :key="batch.id??index"><header><strong :class="['execution-state',batch.state]">{{state(batch.state)}}</strong><small>{{batch.mode==='append'?'Adição de registros':batch.mode==='replace'?'Substituição da base':'Modo não informado'}}</small></header><p v-if="batch.filename" class="resource-note">{{batch.filename}}</p><dl><div><dt>Início</dt><dd>{{date(batch.created_at)}}</dd></div><div><dt>Término</dt><dd>{{date(batch.finished_at)}}</dd></div><div><dt>Registros no lote</dt><dd>{{number(batch.rows_total)}}</dd></div><div><dt>Inseridos</dt><dd>{{number(batch.rows_inserted)}}</dd></div><div><dt>Substituídos</dt><dd>{{number(batch.rows_superseded)}}</dd></div><div><dt>Com falha</dt><dd>{{number(batch.rows_failed)}}</dd></div></dl><small v-if="batch.id" class="execution-id">Lote {{batch.id}}</small></article></div><p v-if="result.has_more" class="resource-note">O histórico foi limitado às primeiras {{result.limit}} importações retornadas.</p></template>
   <template v-if="result.health"><dl class="resource-facts"><div v-for="fact in healthFacts" :key="fact[0]"><dt>{{fact[0]}}</dt><dd>{{fact[1]}}</dd></div></dl><h4>Disponibilidade nas últimas 24 horas</h4><div class="agent-availability"><span v-for="(bucket,index) in result.health.timeline" :key="index" :class="bucket.state" :title="date(bucket.at)+' · '+state(bucket.state)" role="img" :aria-label="date(bucket.at)+' · '+state(bucket.state)"></span></div><p class="resource-note">Verde: disponível · Amarelo: degradado · Cinza: offline ou sem informação.</p></template>
   <template v-if="result.events"><p v-if="!result.events.length" class="resource-note">Nenhuma ocorrência aberta retornada para este tenant.</p><article v-for="(event,index) in result.events" :key="index" class="agent-event"><strong>{{event.name||'Ocorrência de carga'}}</strong><span class="execution-state failed">{{state(event.state)}}</span><p class="resource-note">Prevista: {{date(event.expected_at)}}<template v-if="event.started_at"> · Iniciada: {{date(event.started_at)}}</template><template v-if="event.recovered_at"> · Recuperada: {{date(event.recovered_at)}}</template></p><p v-if="event.message" class="resource-note">{{event.message}}</p></article></template>
   <p class="catalog-footnote">Consultado em {{date(result.checked_at)}} · Brasília. Esta consulta não executa cargas ou altera os recursos.</p>
  </div>
 </section>
</template>

<style scoped>
.resource-inspector .execution-list article{min-width:0;overflow-wrap:anywhere}.execution-state.completed{background:#eaf2ff;color:#2c66ac}.execution-state.partial{background:#fff5df;color:#986519}.execution-state.reverted{background:#edf1f7;color:#627693}
</style>
